	/*
     * @param	event CreateMerchantEvent
     */
    @EventHandler( payloadType=CreateMerchantEvent.class )
    public void handle( CreateMerchantEvent event) {
	    LOGGER.info("handling CreateMerchantEvent - " + event );
	    Merchant entity = new Merchant();
            entity.setMerchantId( event.getMerchantId() );
            entity.setName( event.getName() );
            entity.setMcc( event.getMcc() );
            entity.setUrl( event.getUrl() );
            entity.setCountry( event.getCountry() );
            entity.setSettlementCurrency( event.getSettlementCurrency() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMerchant( entity );
    }

    /*
     * @param	event UpdateMerchantEvent
     */
    @EventHandler( payloadType=UpdateMerchantEvent.class )
    public void handle( UpdateMerchantEvent event) {
    	LOGGER.info("handling UpdateMerchantEvent - " + event );
    	
	    Merchant entity = new Merchant();
            entity.setMerchantId( event.getMerchantId() );
            entity.setName( event.getName() );
            entity.setMcc( event.getMcc() );
            entity.setUrl( event.getUrl() );
            entity.setCountry( event.getCountry() );
            entity.setSettlementCurrency( event.getSettlementCurrency() );
            entity.setTerminals( event.getTerminals() );
            entity.setPaymentContracts( event.getPaymentContracts() );
            entity.setPayouts( event.getPayouts() );
            entity.setSettlements( event.getSettlements() );
            entity.setDisputes( event.getDisputes() );
            entity.setInvoices( event.getInvoices() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindMerchant( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllMerchant( entity );        
    }
    
