    /**
     * Method to retrieve the Merchant via an MerchantPrimaryKey.
     * @param 	id Long
     * @return 	Merchant
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Merchant handle( FindMerchantQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getMerchantId() );
    }
    
    /**
     * Method to retrieve a collection of all Merchants
     *
     * @param	query	FindAllMerchantQuery 
     * @return 	List<Merchant> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Merchant> handle( FindAllMerchantQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindMerchant,
 * but only if the id matches
 *
 * @param		entity	Merchant
 */
	protected void emitFindMerchant( Merchant entity ) {
		LOGGER.info("handling emitFindMerchant" );
		
	    queryUpdateEmitter.emit(FindMerchantQuery.class,
	                            query -> query.getFilter().getMerchantId().equals(entity.getMerchantId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllMerchant
	 * 
	 * @param		entity	Merchant
	 */
	protected void emitFindAllMerchant( Merchant entity ) {
		LOGGER.info("handling emitFindAllMerchant" );
		
	    queryUpdateEmitter.emit(FindAllMerchantQuery.class,
	                            query -> true,
	                            entity);
	}

